!! Golden comparison of the BL99 building blocks against the Icepack column
!! physics: conductivity (both options, a (T, S, rhoi) table and 48 columns of
!! 1, 2, 4 and 8 layers with and without snow), the tridiagonal matrix rows
!! (24 cases: every snow / cold-surface combination, 1, 2, 4 and 8 layers),
!! the Thomas solver (12 systems, two not diagonally dominant) and
!! `init_vertical_profile` (27 columns for each constant set, including thin
!! snow, a round-off warm snow, a layer at its melting point, ice at -90 degC
!! and fresh ice).
!!
!! The tables are 17-significant-digit literals produced by calling the real
!! upstream routines (the oracle driver for this PR).  The conductivity,
!! matrix and solver tables do not depend on the constant set (only `ksno`,
!! `kice`, `puny` and `rhoi`, equal in both sets; `rhoi` is varied inside the
!! table); the profile table is checked against both.
!!
!! Tolerances.  The port performs the same operations in the same order as
!! upstream.  CPU builds (FMA contraction off): the measured worst difference
!! is exactly zero for every table, and the tolerance is zero (bitwise).  The
!! GPU build contracts multiply-adds in host code too, which moves the matrix
!! rows and the solve by round-off amplified by cancellation, so the GPU
!! tolerance is 1e-12, and the comparison is SCALE-AWARE: relative to
!! `max(|reference|, scale)` with `scale` the largest entry of the case (rows
!! and solution), or 1 for the profile fields.  Measured worst on the V100
!! build: 4.3e-16 (conductivity
!! 1.2e-16, matrix rows 2.0e-16, solver 4.3e-16, profile 4.3e-16, nilyr 1/2/4/7/8
!! included); 1e-12 leaves a wide margin.
module test_cice_golden_bl99_pieces
   use, intrinsic :: iso_fortran_env, only: int32
   use testdrive, only: new_unittest, unittest_type, error_type, test_failed
   use rdb_constants, only: wp
   use rdb_ice_params, only: ice_constants_t, ice_constants, ICE_CONSTANTS_ICEPACK, ICE_CONSTANTS_CESM
   use rdb_ice_bl99, only: ICE_NMAT_MAX, ice_layer_conductivity, ice_conductivity, ice_matrix_calc_Tsfc, &
                           ice_tridiag_solver
   use rdb_ice_vprofile, only: ice_init_vertical_profile
   implicit none
   private

   public :: collect_cice_golden_bl99_pieces_tests

#ifdef RDB_GPU_OFFLOAD
   real(wp), parameter :: TOL = 1.0e-12_wp
#else
   real(wp), parameter :: TOL = 0.0_wp
#endif
   integer, parameter :: NCOLS = 60
   integer, parameter :: NMATS = 30

contains

   subroutine collect_cice_golden_bl99_pieces_tests(testsuite)
      type(unittest_type), allocatable, intent(out) :: testsuite(:)
      testsuite = [ &
                  new_unittest("conductivity_scalar_table", test_cond_scalar), &
                  new_unittest("conductivity_columns", test_cond_cols), &
                  new_unittest("matrix_rows", test_matrix), &
                  new_unittest("tridiag_solver", test_tridiag), &
                  new_unittest("vertical_profile_icepack_set", test_vprof_icepack), &
                  new_unittest("vertical_profile_cesm_set", test_vprof_cesm) &
                  ]
   end subroutine collect_cice_golden_bl99_pieces_tests

   pure function rel(g, e, scale) result(d)
      !! Difference scaled by `max(|e|, scale)`.  A NaN in `g` propagates
      !! (callers accumulate with the NaN-proof `.not. (d <= worst)`).
      real(wp), intent(in) :: g, e, scale
      real(wp) :: d
      d = abs(g - e)/max(abs(e), scale)
   end function rel

   subroutine fail_if_worse(error, label, worst, tol)
      type(error_type), allocatable, intent(inout) :: error
      character(len=*), intent(in) :: label
      real(wp), intent(in) :: worst, tol
      character(len=160) :: msg
      if (.not. (worst <= tol)) then
         write (msg, '(a,a,es10.3,a,es10.3)') label, ": worst relative difference ", worst, " > tolerance ", tol
         call test_failed(error, trim(msg))
      end if
   end subroutine fail_if_worse

   subroutine test_cond_scalar(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(5, 396), worst, d, k
      type(ice_constants_t) :: c
      integer :: i

      call load_cond_scalar(a)
      c = ice_constants(ICE_CONSTANTS_ICEPACK)
      worst = 0.0_wp
      do i = 1, 396
         c%rhoi = a(2, i)
         k = ice_layer_conductivity(a(3, i), a(4, i), c, nint(a(1, i)))
         d = rel(k, a(5, i), 1.0_wp)
         if (.not. (d <= worst)) worst = d
      end do
      call fail_if_worse(error, "conductivity table", worst, TOL)
   end subroutine test_cond_scalar

   subroutine test_cond_cols(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(31, NCOLS), worst, d, kh(ICE_NMAT_MAX)
      type(ice_constants_t) :: c
      integer :: i, k, nil, nmat
      integer(int32) :: ierr
      logical :: l_snow

      call load_cond_cols(a)
      c = ice_constants(ICE_CONSTANTS_ICEPACK)
      worst = 0.0_wp
      ierr = 0_int32
      do i = 1, NCOLS
         nil = nint(a(2, i))
         nmat = nil + 2
         l_snow = a(3, i) > 0.5_wp
         kh = 0.0_wp
         call ice_conductivity(l_snow, nil, 1, a(4, i), a(5, i), a(6:5 + nil, i), a(6 + nil:5 + 2*nil, i), c, &
                               nint(a(1, i)), kh, ierr)
         do k = 1, nmat
            d = rel(kh(k), a(5 + 2*nil + k, i), maxval(abs(a(6 + 2*nil:5 + 2*nil + nmat, i))))
            if (.not. (d <= worst)) worst = d
         end do
      end do
      if (ierr /= 0_int32) call test_failed(error, "error bits set")
      if (allocated(error)) return
      call fail_if_worse(error, "conductivity columns", worst, TOL)
   end subroutine test_cond_cols

   subroutine test_matrix(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(84, NMATS), worst, d, sc
      real(wp) :: sb(ICE_NMAT_MAX), dg(ICE_NMAT_MAX), sp(ICE_NMAT_MAX), rh(ICE_NMAT_MAX)
      integer :: i, k, nil, nmat, o
      integer(int32) :: ierr

      call load_matrix(a)
      worst = 0.0_wp
      ierr = 0_int32
      do i = 1, NMATS
         nil = nint(a(1, i))
         nmat = nil + 2
         sb = 0.0_wp; dg = 0.0_wp; sp = 0.0_wp; rh = 0.0_wp
         ! layout: nil l_snow l_cold Tsf Tbot fsurfn dfsurf_dT Tin(nil) Tsn kh(nmat) Ssw Isw(nil) etai(nil) etas | 4 x nmat
         call ice_matrix_calc_Tsfc(a(2, i) > 0.5_wp, a(3, i) > 0.5_wp, nil, 1, a(4, i), a(5, i), a(6, i), a(7, i), &
                                   a(8:7 + nil, i), a(8 + nil:8 + nil, i), a(9 + nil:8 + nil + nmat, i), &
                                   a(9 + nil + nmat:9 + nil + nmat, i), a(10 + nil + nmat:9 + 2*nil + nmat, i), &
                                   a(10 + 2*nil + nmat:9 + 3*nil + nmat, i), a(10 + 3*nil + nmat:10 + 3*nil + nmat, i), &
                                   sb, dg, sp, rh, ierr)
         o = 10 + 3*nil + nmat
         sc = maxval(abs(a(o + 1:o + 4*nmat, i)))
         do k = 1, nmat
            d = rel(sb(k), a(o + k, i), sc)
            if (.not. (d <= worst)) worst = d
            d = rel(dg(k), a(o + nmat + k, i), sc)
            if (.not. (d <= worst)) worst = d
            d = rel(sp(k), a(o + 2*nmat + k, i), sc)
            if (.not. (d <= worst)) worst = d
            d = rel(rh(k), a(o + 3*nmat + k, i), sc)
            if (.not. (d <= worst)) worst = d
         end do
      end do
      if (ierr /= 0_int32) call test_failed(error, "error bits set")
      if (allocated(error)) return
      call fail_if_worse(error, "matrix rows", worst, TOL)
   end subroutine test_matrix

   subroutine test_tridiag(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(51, 12), worst, d, x(ICE_NMAT_MAX), sc
      integer :: i, k, n
      integer(int32) :: ierr

      call load_tridiag(a)
      worst = 0.0_wp
      ierr = 0_int32
      do i = 1, 12
         n = nint(a(1, i))
         x = 0.0_wp
         sc = maxval(abs(a(1 + 4*n + 1:1 + 5*n, i)))
         call ice_tridiag_solver(n, a(2:1 + n, i), a(2 + n:1 + 2*n, i), a(2 + 2*n:1 + 3*n, i), a(2 + 3*n:1 + 4*n, i), x, ierr)
         do k = 1, n
            d = rel(x(k), a(1 + 4*n + k, i), sc)
            if (.not. (d <= worst)) worst = d
         end do
      end do
      if (ierr /= 0_int32) call test_failed(error, "error bits set")
      if (allocated(error)) return
      call fail_if_worse(error, "tridiagonal solver", worst, TOL)
   end subroutine test_tridiag

   subroutine check_vprof(error, label, g, set)
      type(error_type), allocatable, intent(out) :: error
      character(len=*), intent(in) :: label
      real(wp), intent(in) :: g(32, 27)
      integer, intent(in) :: set
      type(ice_constants_t) :: c
      real(wp) :: worst, d, zq(4), zT(4), Tm(4), zqs(1), zTs(1), hin, hl, hsn, hsl, einit
      integer :: i, k
      integer(int32) :: ierr

      c = ice_constants(set)
      worst = 0.0_wp
      ierr = 0_int32
      do i = 1, 27
         zq = g(5:8, i)
         zqs(1) = g(13, i)
         zT = 0.0_wp
         zTs = 0.0_wp
         Tm = 0.0_wp
         call ice_init_vertical_profile(g(2, i), g(3, i), g(4, i), 4, 1, c, g(1, i) > 0.5_wp, g(9:12, i), zq, zqs, zT, zTs, &
                                        Tm, hin, hl, hsn, hsl, einit, ierr)
         d = rel(hin, g(14, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(hl, g(15, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(hsn, g(16, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(hsl, g(17, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(zqs(1), g(26, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(zTs(1), g(27, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         d = rel(einit, g(32, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         do k = 1, 4
            d = rel(zq(k), g(17 + k, i), 1.0_wp); if (.not. (d <= worst)) worst = d
            d = rel(zT(k), g(21 + k, i), 1.0_wp); if (.not. (d <= worst)) worst = d
            d = rel(Tm(k), g(27 + k, i), 1.0_wp); if (.not. (d <= worst)) worst = d
         end do
      end do
      if (ierr /= 0_int32) call test_failed(error, "error bits set")
      if (allocated(error)) return
      call fail_if_worse(error, label, worst, TOL)
   end subroutine check_vprof

   subroutine test_vprof_icepack(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: g(32, 27)
      call load_vprofile_icepack(g)
      call check_vprof(error, "vertical profile (Icepack set)", g, ICE_CONSTANTS_ICEPACK)
   end subroutine test_vprof_icepack

   subroutine test_vprof_cesm(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: g(32, 27)
      call load_vprofile_cesm(g)
      call check_vprof(error, "vertical profile (CESM set)", g, ICE_CONSTANTS_CESM)
   end subroutine test_vprof_cesm

